  {
    "id": "buildWeatherSummary",
    "type": "core.action.script",
    "typeVersion": "1.1",
    "display": { "label": "Build Weather Summary" },
    "inputs": {
      "script": "const body = $vars.getBellevueWeather1.output.body;\nconst temp = body.current.temperature_2m;\nconst code = body.current.weathercode;\nlet condition;\nif (code === 0) condition = 'clear skies';\nelse if (code <= 3) condition = 'partly cloudy to overcast skies';\nelse if (code <= 48) condition = 'foggy conditions';\nelse if (code <= 55) condition = 'drizzly conditions';\nelse if (code <= 65) condition = 'rainy conditions';\nelse if (code <= 75) condition = 'snowy conditions';\nelse if (code <= 82) condition = 'rain showers';\nelse if (code <= 86) condition = 'snow showers';\nelse if (code <= 99) condition = 'thunderstorms';\nelse condition = 'mixed conditions';\nconst rounded = Math.round(temp);\nconst verdict = temp > 60 ? 'Nice day!' : 'Bring a jacket.';\nconst summary = 'It is currently ' + rounded + ' degrees F in Bellevue with ' + condition + '. ' + verdict;\nreturn { tempF: temp, verdict: verdict, summary: summary };"
